#!/usr/bin/env python3
from pathlib import Path

WEB = Path('src/main/resources/web')
HOSTS = (
    'index.html', 'cvss-v31.html', 'cisa-kev.html', 'epss.html',
    'asset-context.html', 'network-reachability.html', 'business-impact.html',
    'assets.html', 'asset-links.html',
)
MARKER = '<script src="/ui/rbvm-ui.js" defer></script>'
CONTRACT = 'ACTIVE_RISK_METHOD_EXECUTION_UI_V1'
MODULE = r'''  <script>
(()=>{'use strict';
const CONTRACT='ACTIVE_RISK_METHOD_EXECUTION_UI_V1';
const SEMANTICS='EXPLICIT_ACTIVATION_REVISION_EVENT_SHA_AND_DECISION_INPUT_SHA_ONLY_NO_CURRENT_DEFAULT';
const rawFetch=window.fetch.bind(window);let queued=false;
document.documentElement.dataset.activeRiskMethodExecutionUiContract=CONTRACT;
const h=(tag,attrs={},...children)=>{const node=document.createElement(tag);for(const[key,value]of Object.entries(attrs)){if(value==null||value===false)continue;if(key==='class')node.className=value;else if(key==='text')node.textContent=String(value);else if(key.startsWith('on'))node.addEventListener(key.slice(2).toLowerCase(),value);else if(key==='value')node.value=String(value);else node.setAttribute(key,String(value))}for(const child of children.flat())if(child!=null)node.append(child instanceof Node?child:document.createTextNode(String(child)));return node};
const btn=(label,fn,kind='secondary')=>h('button',{class:`button button-${kind}`,type:'button',text:label,onclick:fn});
const call=(text,kind='info')=>h('div',{class:`callout callout-${kind}`,text});
const pair=(label,value,mono=false)=>h('div',{class:'detail'},h('dt',{text:label}),h('dd',{class:mono?'mono':'',text:value??'—'}));
const title=value=>String(value||'').toLowerCase().replace(/(^|[_\s-])\w/g,part=>part.toUpperCase()).replaceAll('_',' ');
const exactRevision=value=>/^[1-9]\d*$/.test(String(value).trim())?String(value).trim():null;
const exactSha=value=>/^[a-f0-9]{64}$/.test(String(value).trim())?String(value).trim():null;
async function api(path,options={}){const response=await rawFetch(path,{...options,cache:'no-store'});let json=null;try{json=await response.clone().json()}catch(_){}if(!response.ok){const error=new Error(json?.detail||json?.title||`HTTP ${response.status}`);error.status=response.status;error.code=json?.code||'';throw error}return{response,json}}
function schedule(){if(queued)return;queued=true;queueMicrotask(()=>{queued=false;enhance()})}
function enhance(){const drawer=document.querySelector('.drawer');if(!drawer)return;const body=drawer.querySelector('.drawer-body'),tab=body?.querySelector('[data-risk-method-policy][aria-selected="true"]');if(!body||!tab||body.querySelector('[data-active-risk-method-execution-ui]'))return;const root=h('section',{class:'panel','data-active-risk-method-execution-ui':'true'},h('div',{class:'panel-header'},h('div',{},h('h2',{class:'panel-title',text:'Execute selected risk method'}),h('p',{class:'panel-subtitle',text:'V27 exact historical activation + exact Decision Input V3 · immutable execution provenance'}))),h('div',{class:'panel-body','data-active-risk-execution-body':'true'}));body.append(root);render(root)}
function bindingView(payload,response,label){if(payload?.executionSemantics!==SEMANTICS)return call('Execution response does not advertise the required explicit identity semantics. It is not presented as valid execution provenance.','warning');const binding=payload.binding||{},status=payload.executionStatus;return h('section',{class:'panel'},h('div',{class:'panel-header'},h('div',{},h('h3',{class:'panel-title',text:label}),h('p',{class:'panel-subtitle',text:status==='REPLAYED'?'Exact immutable execution binding replayed without selecting another method.':'Exact immutable execution provenance'}))),h('div',{class:'panel-body'},status?h('div',{class:'inline-actions'},h('span',{class:'badge state-present',text:status==='INSERTED'?'Execution binding inserted':'Execution binding replayed'})):null,h('dl',{class:'details-grid'},pair('Activation revision',binding.activationRevision),pair('Activation event SHA-256',binding.activationEventSha256,true),pair('Policy revision',binding.policyRevision),pair('Policy SHA-256',binding.policySha256,true),pair('Selection role',title(binding.selectionRole)),pair('Method family',title(binding.methodFamily)),pair('Method ID',binding.methodId,true),pair('Method version',binding.methodVersion),pair('Method SHA-256',binding.methodSha256,true),pair('Decision Input SHA-256',binding.inputSnapshotSha256,true),pair('Result family',title(binding.resultFamily)),pair('Result SHA-256',binding.resultSha256,true),pair('Binding SHA-256',binding.bindingSha256,true),pair('Canonical format',binding.canonicalPayloadFormat,true),pair('Result location',payload.resultLocation,true),pair('ETag',response?.headers.get('ETag')||'—',true),pair('Location',response?.headers.get('Location')||'—',true))))}
function executeError(error){if(error.status===403)return'Operator role is required to execute an exact active risk method selection.';if(error.status===404)return'The exact activation identity or Decision Input SHA does not exist. No fallback identity is selected.';if(error.status===409)return error.code==='RISK_METHOD_SELECTION_ACTIVATION_CLEARED'?'That exact activation event is CLEARED. The UI will not fall back to another policy.':'The exact selected method is unavailable or immutable execution content conflicts. No alternate method is selected.';if(error.status===422)return'Execution requires an exact persisted Decision Input Snapshot V3 identity.';if(error.status===500)return'Persisted activation, policy, method, input, or result identities failed exact integrity verification.';if(error.status===503)return'V27 Active Risk Method Execution persistence is unavailable in this runtime.';return error.message}
function render(root){const body=root.querySelector('[data-active-risk-execution-body]');body.append(call('Execution is a separate auditable operation. Enter one exact historical activation revision + event SHA and one exact Decision Input V3 SHA. This UI never runs the current activation, never selects by policy revision order, and never rebuilds evidence.'));const activationRevision=h('input',{type:'number',min:'1',step:'1',inputmode:'numeric','aria-label':'Exact execution activation revision',placeholder:'Activation revision'}),activationSha=h('input',{type:'text',maxlength:'64',autocomplete:'off',spellcheck:'false','aria-label':'Exact execution activation event SHA-256',placeholder:'64-character lowercase event SHA-256'}),inputSha=h('input',{type:'text',maxlength:'64',autocomplete:'off',spellcheck:'false','aria-label':'Exact execution Decision Input SHA-256',placeholder:'64-character lowercase Decision Input SHA-256'});activationRevision.value='';activationSha.value='';inputSha.value='';const status=h('div',{class:'status-message',role:'status','aria-live':'polite'}),result=h('div',{class:'stack','data-active-risk-execution-result':'true'});const execute=btn('Execute exact identities',async()=>{const revision=exactRevision(activationRevision.value),eventSha=exactSha(activationSha.value),snapshotSha=exactSha(inputSha.value);if(!revision||!eventSha||!snapshotSha){status.className='status-message error';status.textContent='Enter an exact positive activation revision, lowercase activation event SHA-256, and lowercase Decision Input SHA-256.';return}execute.disabled=true;status.className='status-message';status.textContent='Executing or replaying the exact immutable identities…';try{const response=await api(`/api/v1/active-risk-method-executions/${revision}/${eventSha}/${snapshotSha}`,{method:'POST'});status.textContent=response.json?.executionStatus==='REPLAYED'?'Exact execution binding replayed; the selected risk method was not re-executed.':'Exact risk method executed and immutable binding inserted.';result.replaceChildren(bindingView(response.json,response.response,'Execution result'))}catch(error){status.className='status-message error';status.textContent=executeError(error)}finally{execute.disabled=false}},'primary');body.append(h('section',{class:'panel'},h('div',{class:'panel-header'},h('div',{},h('h3',{class:'panel-title',text:'Execute exact historical selection'}),h('p',{class:'panel-subtitle',text:'All execution selectors start empty and remain operator-supplied. No browser state or active-policy lookup pre-fills them.'}))),h('div',{class:'panel-body'},h('div',{class:'form-grid'},h('label',{},h('span',{text:'Activation revision'}),activationRevision),h('label',{},h('span',{text:'Activation event SHA-256'}),activationSha),h('label',{},h('span',{text:'Decision Input V3 SHA-256'}),inputSha)),status,h('div',{class:'form-actions'},execute),result)));const bindingSha=h('input',{type:'text',maxlength:'64',autocomplete:'off',spellcheck:'false','aria-label':'Exact execution binding SHA-256 to read',placeholder:'64-character lowercase binding SHA-256'});bindingSha.value='';const readStatus=h('div',{class:'status-message',role:'status','aria-live':'polite'}),readResult=h('div',{class:'stack','data-active-risk-binding-result':'true'});const read=btn('Read exact execution binding',async()=>{const sha=exactSha(bindingSha.value);if(!sha){readStatus.className='status-message error';readStatus.textContent='Enter the exact lowercase execution binding SHA-256.';return}read.disabled=true;readStatus.className='status-message';readStatus.textContent='Reading exact immutable execution binding…';try{const response=await api(`/api/v1/active-risk-method-execution-bindings/${sha}`);readStatus.textContent='Exact execution binding loaded.';readResult.replaceChildren(bindingView(response.json,response.response,'Exact execution binding'))}catch(error){readStatus.className='status-message error';readStatus.textContent=error.status===404?'No execution binding matches that exact SHA. No fallback binding is selected.':error.status===503?'V27 Active Risk Method Execution persistence is unavailable in this runtime.':error.message}finally{read.disabled=false}},'secondary');body.append(h('section',{class:'panel'},h('div',{class:'panel-header'},h('div',{},h('h3',{class:'panel-title',text:'Read exact execution binding'}),h('p',{class:'panel-subtitle',text:'Historical replay is by one canonical binding SHA only; there is no execution or binding collection lookup.'}))),h('div',{class:'panel-body'},h('div',{class:'form-grid'},h('label',{},h('span',{text:'Binding SHA-256'}),bindingSha)),readStatus,h('div',{class:'form-actions'},read),readResult)),call('Execution provenance does not create Priority, Treatment, SLA, remediation deadline, ownership, or remediation workflow semantics. Native Formula and derived-method results remain separate contracts.'))}
new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener('DOMContentLoaded',schedule);
})();
  </script>
'''

reference = (WEB / HOSTS[0]).read_text(encoding='utf-8')
for name in HOSTS:
    path = WEB / name
    text = path.read_text(encoding='utf-8')
    if text != reference:
        raise SystemExit(f'{name}: Frontend V2 hosts are not byte-identical before patch')
    if CONTRACT in text:
        continue
    if text.count(MARKER) != 1:
        raise SystemExit(f'{name}: expected one external UI script marker')
    path.write_text(text.replace(MARKER, MODULE + '  ' + MARKER, 1), encoding='utf-8')
print('Active Risk Method Execution UI V1 hosts: PATCHED')
